UPDATE community_post p SET repost_count = (
    SELECT COUNT(*) FROM community_post_repost r WHERE r.post_id = p.id AND r.active = TRUE
) WHERE p.id = #{postId}

mapper.select:
SELECT id, actor_user_id, target_user_id, relation_type, active, created_at, updated_at
FROM community_user_relation_control
WHERE actor_user_id = #{actorUserId} AND target_user_id = #{targetUserId} AND relation_type = #{relationType}

SELECT post_id FROM community_recommendation_feedback
WHERE user_id = #{userId} AND feedback_type = 'NOT_INTERESTED' AND active = TRUE AND post_id IN
#{id}
